// Auditor extension of the RULE-04 boundary negative to every checked workspace
// owner (browser, public and server scopes, including web and both engine
// facades), with nested relative paths and static/dynamic/re-export forms.
import assert from 'node:assert/strict';
import { relative } from 'node:path';
import { join } from 'node:path';
const { checkSource, boundaryContext } = await import('./scripts/check-boundaries.mjs');
const context = boundaryContext();
const owners = context.owners.filter(o => ['browser', 'public', 'server'].includes(o.scope));
let refused = 0;
for (const owner of owners) for (const target of ['scripts/rules/scenario-runtime.mjs', 'scripts/rules/scenario-build.mjs', 'scripts/rules/certification.mjs', 'tests/rules/scenarios.test.mjs']) {
  for (const depth of ['src/probe.ts', 'src/deep/nested/probe.ts']) {
    const file = join(owner.path, depth), up = '../'.repeat(relative(context.root, file).split('/').length - 1);
    for (const loader of [`import '${up}${target}';`, `void import('${up}${target}');`, `export * from '${up}${target}';`]) {
      assert.throws(() => checkSource(file, context, loader), /Forbidden (engine|browser) import/, `${owner.name} ${depth} ${loader}`); refused++;
    }
  }
}
console.log(JSON.stringify({ owners: owners.map(o => `${o.name}:${o.scope}`), refusedImports: refused, notCheckedScopes: context.owners.filter(o => !owners.includes(o)).map(o => `${o.name}:${o.scope}`) }));
console.log('PASS every browser/public/server owner (including web, engine-lab and engine-adapter) refuses static, dynamic and re-export imports of RULE-04 test tooling');
